package com.selfleveling.self_leveling

import android.os.Handler
import android.os.Looper
import android.util.Log

/**
 * Handles the asynchronous communication between Kotlin (Native) and Dart (Flutter).
 *
 * It takes a Base Payload generated by the EscalationEvaluator, asks Flutter to
 * generate Rich wording (Headline, Body, Hints) based on real-time context,
 * and if Flutter is unavailable or times out, it gracefully falls back to the
 * native wording.
 */
object MessagingBridge {
    private const val TAG = "SL.MessagingBridge"
    private const val TIMEOUT_MS = 2000L // Fast timeout to avoid freezing the pipeline

    private val mainHandler = Handler(Looper.getMainLooper())

    fun requestGeneratedMessage(
        basePayload: InterventionPayload,
        contextIgnoredCount: Int,
        distractionScore: Double,
        callback: (InterventionPayload) -> Unit
    ) {
        val methodChannel = MainActivity.methodChannel

        // If the Flutter Engine is dead or not attached, fallback instantly
        if (methodChannel == null) {
            Log.w(TAG, "FlutterEngine not attached. Falling back to native strings.")
            callback(basePayload)
            return
        }

        val requestMap = mapOf(
            "contractVersion" to RuntimeContract.VERSION,
            "payloadSignature" to listOf(
                basePayload.stage,
                basePayload.packageName,
                basePayload.reentryCount,
                basePayload.isLimitedAccess,
                basePayload.limitedAccessRemainingSec,
            ).joinToString(":"),
            "runtimeEventId" to listOf(
                "runtime",
                basePayload.stage,
                basePayload.packageName,
                basePayload.reentryCount,
                System.currentTimeMillis(),
            ).joinToString(":"),
            "stage" to basePayload.stage,
            "distractionScore" to distractionScore,
            "ignoredWarnings" to contextIgnoredCount,
            "packageName" to basePayload.packageName,
            "appName" to basePayload.appName,
            "reason" to basePayload.reason,
            "reentryCount" to basePayload.reentryCount,
            "xpPenalty" to basePayload.xpPenalty,
            "limitedAccessRemainingSec" to basePayload.limitedAccessRemainingSec,
            "isLimitedAccess" to basePayload.isLimitedAccess,
            "focusModeActive" to TrackingService.currentInstance?.isFocusModeActive,
            "appCategory" to AppClassifier.classify(basePayload.packageName, emptyMap()),
            "requestedAt" to System.currentTimeMillis(),
        )

        var fallbackDelivered = false
        var finalized = false

        // Timeout safety
        val timeoutRunnable = Runnable {
            if (!fallbackDelivered && !finalized) {
                fallbackDelivered = true
                Log.w(TAG, "${RuntimeMethods.GENERATE_INTERVENTION} request timed out. Using fallback.")
                callback(basePayload)
            }
        }
        mainHandler.postDelayed(timeoutRunnable, TIMEOUT_MS)

        // Invoke Flutter MethodChannel (Must be on UI Thread)
        mainHandler.post {
            try {
                methodChannel.invokeMethod(RuntimeMethods.GENERATE_INTERVENTION, requestMap, object : io.flutter.plugin.common.MethodChannel.Result {
                    override fun success(result: Any?) {
                        if (finalized) return
                        finalized = true
                        mainHandler.removeCallbacks(timeoutRunnable)

                        try {
                            val map = result as? Map<*, *>
                            if (map != null) {
                                val enrichedPayload = basePayload.copy(
                                    headline = map["headline"] as? String,
                                    body = map["body"] as? String,
                                    actionLabel = map["actionLabel"] as? String,
                                    tone = map["tone"] as? String,
                                    language = map["language"] as? String,
                                    recommendationTitle = map["recommendationTitle"] as? String,
                                    recommendationText = map["recommendationText"] as? String
                                )
                                Log.d(TAG, "Successfully received rich payload from Dart.")
                                callback(enrichedPayload)
                            } else {
                                Log.w(TAG, "Return type from ${RuntimeMethods.GENERATE_INTERVENTION} was null/invalid.")
                                if (!fallbackDelivered) {
                                    callback(basePayload)
                                }
                            }
                        } catch (e: Exception) {
                            Log.e(TAG, "Error parsing rich payload", e)
                            if (!fallbackDelivered) {
                                callback(basePayload)
                            }
                        }
                    }

                    override fun error(errorCode: String, errorMessage: String?, errorDetails: Any?) {
                        if (finalized) return
                        finalized = true
                        mainHandler.removeCallbacks(timeoutRunnable)
                        Log.e(TAG, "${RuntimeMethods.GENERATE_INTERVENTION} error: $errorCode - $errorMessage")
                        if (!fallbackDelivered) {
                            callback(basePayload)
                        }
                    }

                    override fun notImplemented() {
                        if (finalized) return
                        finalized = true
                        mainHandler.removeCallbacks(timeoutRunnable)
                        Log.w(TAG, "${RuntimeMethods.GENERATE_INTERVENTION} not implemented by Flutter")
                        if (!fallbackDelivered) {
                            callback(basePayload)
                        }
                    }
                })
            } catch (e: Exception) {
                Log.e(TAG, "Exception invoking methodChannel", e)
                if (!finalized) {
                    finalized = true
                    mainHandler.removeCallbacks(timeoutRunnable)
                    if (!fallbackDelivered) {
                        callback(basePayload)
                    }
                }
            }
        }
    }
}
